'use strict';
const model=StallSlot.createModel(),money=StallSlot.money;
const state={view:'vendor',selected:'B09',availableOnly:false,adminFilter:'all'};
const main=document.getElementById('main'),dialog=document.getElementById('flow-dialog');
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={available:'Available',requested:'Requested',held:'Held',booked:'Booked'};
function stallPosition(stall){
 const sideRows=[25,34,43,59,68,77];
 if(stall.row===0)return {left:9+stall.col*14,top:12};
 if(stall.row===1)return {left:6,top:sideRows[stall.col]};
 if(stall.row===2)return {left:84,top:sideRows[stall.col]};
 return {left:[7,20,33,57,70,83][stall.col],top:88};
}
const arrow='<span class="arrow" aria-hidden="true">↗</span>';
let toastTimer;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function setView(view){if(!['vendor','admin'].includes(view))throw Error('Unknown view.');state.view=view;render();}
function render(){const pending=model.list().filter(s=>s.status==='requested').length;document.getElementById('pending-badge').textContent=pending;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});state.view==='vendor'?renderVendor():renderAdmin();}
function renderVendor(){const stalls=model.list(),s=model.get(state.selected),available=stalls.filter(s=>s.status==='available').length;
main.innerHTML=`<section class="intro"><div><div class="eyebrow">The Courtyard Market / Hyderabad · sample event</div><h1>Find your <em>little corner.</em></h1></div><div class="event-meta"><div class="date-badge"><small>OCT</small><strong>18</strong></div><div><b>Sunday, 18 October 2026</b><span>4 PM — 10 PM</span></div><div><b>Courtyard Grounds</b><span>Fictional venue, Hyderabad</span></div></div></section>
<div class="workspace"><section aria-label="Choose a stall"><div class="map-card"><div class="map-toolbar"><div class="map-title">Choose your space <span>24 stalls · courtyard market</span></div><label class="filter"><input type="checkbox" id="available-filter" ${state.availableOnly?'checked':''}>Available only</label></div><div class="map-scroll"><div class="floorplan" role="group" aria-label="Interactive venue map. Choose a numbered stall for details."><span class="plan-stamp">COURTYARD / 01</span><span class="north" aria-label="North">N ↑</span><div class="zone-label zone-north">NORTH · BRANDS</div><div class="courtyard-space"><span class="eyebrow">THE HEART OF THE MARKET</span><strong>Open courtyard</strong><span>An open space to browse, meet & gather.</span></div><div class="zone-label zone-food">SOUTH · FOOD & DRINK</div><div class="side-exit">← EXIT</div><div class="entry-path" aria-hidden="true"></div>${stalls.map(b=>`<button type="button" class="stall side-${b.row} ${b.status} ${b.id===s.id?'selected':''} ${state.availableOnly&&b.status!=='available'?'dimmed':''}" style="left:${stallPosition(b).left}%;top:${stallPosition(b).top}%" data-stall="${b.id}" aria-label="Stall ${b.id}, ${labels[b.status]}, ${money(b.price)}, ${b.zone}" aria-pressed="${b.id===s.id}" ${state.availableOnly&&b.status!=='available'?'disabled':''}><strong>${b.id}</strong><small>${b.status==='available'?money(b.price):labels[b.status]}</small></button>`).join('')}<div class="entry" aria-label="Main entrance">↑ IN</div></div></div><div class="map-bottom"><div class="legend">${Object.keys(labels).map(k=>`<span><i class="swatch ${k}" aria-hidden="true"></i>${labels[k]}</span>`).join('')}</div><p>Tap any stall for details</p></div></div><div class="under-map"><div class="availability-copy"><strong>${available}</strong> of 24 stalls available</div><div class="availability-bar" aria-hidden="true"><span style="width:${available/24*100}%"></span></div><span>Sample layout · stalls face the courtyard</span></div></section>
<aside aria-label="Selected stall details"><article class="ticket"><div class="ticket-head"><div class="eyebrow">Selected space</div><div class="ticket-identity"><span class="ticket-number">${s.id}</span><span class="ticket-status">${labels[s.status]}</span></div></div><div class="ticket-body"><h2>${s.power?'A taste of the market.':'A place for your brand.'}</h2><p>${s.power?'A bigger pitch for food and drinks, with an electricity connection included.':'A space for independent brands, handmade finds, and conversations that turn into customers.'}</p><dl class="details-grid"><div><dt>Stall size</dt><dd>${s.size}</dd></div><div><dt>Location</dt><dd>${s.zone}</dd></div><div><dt>Electricity</dt><dd>${s.power?'Included':'Not included'}</dd></div><div><dt>Setup includes</dt><dd>Table + 2 chairs</dd></div></dl><div class="price-row"><strong>${money(s.price)}</strong><span>for the full event</span></div><button class="primary" id="request-button" ${s.status!=='available'?'disabled':''}>${s.status==='available'?'Request this stall':s.status==='requested'?'Request awaiting review':s.status==='held'?'Held for an approved vendor':'This stall is booked'}${arrow}</button><p class="fine">${s.status==='available'?'Request first. Pay only after organiser approval.':'Select another available space on the map.'}</p></div></article><div class="process"><h3>A simple path to your spot</h3><ol><li><span>1</span>Send request</li><li><span>2</span>Get approved</li><li><span>3</span>Pay & confirm</li></ol></div></aside></div>`;
document.querySelectorAll('[data-stall]').forEach(b=>b.addEventListener('click',()=>selectStall(b.dataset.stall)));
document.getElementById('available-filter').addEventListener('change',e=>{state.availableOnly=e.target.checked;if(state.availableOnly&&model.get(state.selected).status!=='available'){const first=model.list().find(s=>s.status==='available');if(first)state.selected=first.id;}renderVendor();document.getElementById('available-filter').focus();});
document.getElementById('request-button').addEventListener('click',()=>openRequest(state.selected));
}
function selectStall(id){model.get(id);state.selected=id;state.view='vendor';render();document.querySelector(`[data-stall="${id}"]`)?.focus({preventScroll:true});}
function openDialog(html){document.getElementById('dialog-content').innerHTML=`<div class="dialog-inner">${html}</div>`;if(!dialog.open)dialog.showModal();dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());}
function dialogHead(title){return `<div class="dialog-top"><h2 id="dialog-title">${title}</h2><button type="button" class="close" data-close aria-label="Close dialog">×</button></div>`;}
function openRequest(id){const s=model.get(id);if(s.status!=='available')return toast('Please choose an available stall.');const categories=s.power?['Food & drink']:['Fashion','Accessories','Art & craft','Home & lifestyle'];
openDialog(`${dialogHead('Make yourself at home.')}<p class="dialog-sub">Tell the organiser a little about your business. This demo uses sample details only.</p><div class="booking-summary"><span>Stall ${s.id} · ${s.size}</span><strong>${money(s.price)}</strong></div><form id="request-form"><label class="field"><span>Your name</span><input name="name" required minlength="2" maxlength="60" autocomplete="off" placeholder="e.g. Alex" value="Alex Demo"></label><label class="field"><span>Business name</span><input name="business" required minlength="2" maxlength="80" autocomplete="off" placeholder="Your brand or stall name" value="${s.power?'Weekend Bakes':'Sunday Studio'}"></label><label class="field"><span>What do you sell?</span><select name="category" required>${categories.map(c=>`<option>${c}</option>`).join('')}</select></label><p id="form-error" class="form-error" role="alert"></p><button class="primary" type="submit">Send demo request ${arrow}</button><p class="fine">No payment required. This is not a real event booking.</p></form>`);
document.getElementById('request-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const result=model.request(id,data);render();showRequestSuccess(result);}catch(err){document.getElementById('form-error').textContent=err.message;}};
}
function showRequestSuccess(s){openDialog(`<div class="success-mark" aria-hidden="true">✓</div>${dialogHead('You’re on the list.')}<p class="success-copy">Your request for <strong>stall ${s.id}</strong> is awaiting organiser review. A request doesn’t confirm your booking or payment.</p><div class="request-ref">REQUEST / ${s.reference}</div><div class="demo-tip">Now try the other side: open the organiser view, approve your request, then simulate checking the deposit.</div><button class="primary" id="switch-organiser">Try the organiser view ${arrow}</button>`);document.getElementById('switch-organiser').onclick=()=>{dialog.close();state.adminFilter='all';setView('admin');};}
function renderAdmin(){const all=model.list(),requests=all.filter(s=>s.status==='requested'),held=all.filter(s=>s.status==='held'),booked=all.filter(s=>s.status==='booked'),occupied=all.filter(s=>s.status!=='available'),rows=occupied.filter(s=>state.adminFilter==='all'||s.status===state.adminFilter),verified=booked.reduce((n,s)=>n+s.price/2,0);const order={requested:0,held:1,booked:2};rows.sort((a,b)=>order[a.status]-order[b.status]);
main.innerHTML=`<section class="intro admin-intro"><div><div class="eyebrow">The Courtyard Market / organiser workspace</div><h1>Good markets. <em>Less admin.</em></h1><p class="admin-note">Review requests, approve vendors, and confirm stalls after checking deposits. This demo lets you try both roles; no real accounts or money are connected.</p></div><button class="small-button" id="back-to-map">View stall map ↗</button></section>
<section class="stats" aria-label="Booking overview"><div class="stat"><span class="stat-label">Awaiting your review</span><strong class="stat-value">${requests.length.toString().padStart(2,'0')}</strong><small>Vendor requests</small></div><div class="stat"><span class="stat-label">Approved & held</span><strong class="stat-value">${held.length.toString().padStart(2,'0')}</strong><small>Waiting for a deposit</small></div><div class="stat"><span class="stat-label">Confirmed stalls</span><strong class="stat-value">${booked.length}<span style="font-size:20px;color:var(--muted)"> / 24</span></strong><small>Deposit marked as verified</small></div><div class="stat"><span class="stat-label">Demo deposits verified</span><strong class="stat-value">${money(verified)}</strong><small>Sample 50% deposit per stall</small></div></section>
<section class="admin-panel"><div class="panel-head"><h2>Vendor requests & bookings</h2><select id="admin-filter" class="select-control" aria-label="Filter bookings by status"><option value="all">All bookings (${occupied.length})</option><option value="requested">Awaiting review (${requests.length})</option><option value="held">Approved & held (${held.length})</option><option value="booked">Confirmed (${booked.length})</option></select></div><div class="table-scroll"><table><thead><tr><th scope="col">Vendor</th><th scope="col">Stall</th><th scope="col">Status</th><th scope="col">Deposit / balance</th><th scope="col">Next step</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${escapeHTML(s.business)}</strong><small>${escapeHTML(s.category)} · ${escapeHTML(s.name)}</small></td><td><strong>${s.id}</strong><small>${s.size}</small></td><td><span class="pill ${s.status}">${s.status==='requested'?'Awaiting review':s.status==='held'?'Approved · held':'Confirmed'}</span></td><td><strong>${money(s.price/2)} ${s.depositVerified?'verified':'due'}</strong><small>${money(s.price/2)} remaining after deposit</small></td><td><div class="row-actions">${s.status==='requested'?`<button class="small-button emphasis" data-approve="${s.id}">Approve request</button><button class="small-button" data-release="${s.id}">Decline</button>`:s.status==='held'?`<button class="small-button emphasis" data-confirm="${s.id}">Check deposit</button><button class="small-button" data-release="${s.id}">Release</button>`:'<span class="table-status-note">✓ Stall confirmed</span>'}</div></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No bookings in this category. Try requesting an available stall.</div>':''}</div></section><p class="admin-note" style="margin-top:18px;font-size:13px">Sample policy: a 50% deposit confirms a stall. Deposits here are simulated; a live event would require the organiser to verify actual receipt.</p>`;
document.getElementById('admin-filter').value=state.adminFilter;document.getElementById('admin-filter').onchange=e=>{state.adminFilter=e.target.value;renderAdmin();document.getElementById('admin-filter').focus();};document.getElementById('back-to-map').onclick=()=>setView('vendor');
document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approveRequest(b.dataset.approve));document.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>openConfirm(b.dataset.confirm));document.querySelectorAll('[data-release]').forEach(b=>b.onclick=()=>openRelease(b.dataset.release));
}
function approveRequest(id){try{model.approve(id);render();toast(`Stall ${id} is held. Check the deposit before confirming.`);}catch(e){toast(e.message);}}
function openConfirm(id){const s=model.get(id);openDialog(`${dialogHead('Check the deposit.')}<p class="dialog-sub">${escapeHTML(s.business)} · stall ${s.id}</p><div class="booking-summary"><span>Expected 50% deposit</span><strong>${money(s.price/2)}</strong></div><p class="dialog-sub">For a real event, check your bank or payment app. A screenshot or payment reference alone is not verification.</p><form id="confirm-form"><label class="check-label"><input type="checkbox" name="verified" required><span>Simulate that I have verified receipt of the ${money(s.price/2)} deposit.</span></label><p class="form-error" id="form-error" role="alert"></p><button class="primary" type="submit">Confirm demo booking ${arrow}</button><p class="fine">No money is moved or verified by this demo.</p></form>`);document.getElementById('confirm-form').onsubmit=e=>{e.preventDefault();try{model.confirm(id,e.target.elements.verified.checked);dialog.close();render();toast(`Stall ${id} is confirmed. The venue map is updated.`);}catch(err){document.getElementById('form-error').textContent=err.message;}};}
function openRelease(id){const s=model.get(id);openDialog(`${dialogHead(s.status==='requested'?'Decline this request?':'Release this stall?')}<p class="dialog-sub">${escapeHTML(s.business)} will be removed from stall ${id}, and the space will become available again. No message will be sent.</p><div class="dialog-buttons"><button class="small-button" data-close>Keep it</button><button class="primary" id="release-confirm">${s.status==='requested'?'Decline request':'Release stall'} ${arrow}</button></div>`);document.getElementById('release-confirm').onclick=()=>{try{model.release(id);dialog.close();render();toast(`Stall ${id} is available again.`);}catch(err){toast(err.message);}};}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelector('.brand').onclick=e=>{e.preventDefault();setView('vendor');};
render();
// Structured controls share the same state and validation as the visible demo.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'list_demo_stalls',description:'Read the fictional event stalls and current in-session booking states. No real bookings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({stalls:model.list(),demo:true})});register({name:'select_demo_stall',description:'Show a stall on the venue map. Does not request or reserve it.',inputSchema:{type:'object',properties:{stallId:{type:'string'}},required:['stallId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.stallId!=='string')throw Error('stallId must be a string.');const s=model.get(input.stallId);selectStall(s.id);return {selectedStall:s.id,status:s.status};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
